from hypothesis import given, strategies as st, settings
import impl


def ref_pattern_matches(pattern, value):
    if pattern == '*':
        return True
    if pattern.endswith('*'):
        return value.startswith(pattern[:-1])
    return pattern == value


def ref_principal_matches(principal, subject, roles):
    if principal == '*':
        return True
    if principal.startswith('user:'):
        return principal[5:] == subject
    if principal.startswith('role:'):
        return principal[5:] in roles
    return False


def ref_authorize(request, policies):
    decision_allow = False
    for p in policies:
        if (ref_principal_matches(p['principal'], request['subject'], request['roles'])
                and ref_pattern_matches(p['action'], request['action'])
                and ref_pattern_matches(p['resource'], request['resource'])):
            if p['effect'] == 'DENY':
                return 'DENY'
            if p['effect'] == 'ALLOW':
                decision_allow = True
    return 'ALLOW' if decision_allow else 'DENY'


names = st.sampled_from(['alice', 'bob', 'admin', 'contractor', 's3:GetObject', 's3:Get', 's3:PutObject', 'docs/reports/x', 'docs/reportsQ1', 'docs/reports/', '*'])
principals = st.sampled_from(['*', 'user:alice', 'user:bob', 'role:admin', 'role:contractor', 'user:al*', 'role:*'])
act_res = st.sampled_from(['*', 's3:Get*', 's3:Get', 's3:GetObject', 'docs/reports/*', 'docs/reportsQ1', 's3:*Object', 'docs/reports/'])
effects = st.sampled_from(['ALLOW', 'DENY'])
roles_strat = st.lists(st.sampled_from(['admin', 'contractor', 'viewer']), max_size=3)

policy_strat = st.fixed_dictionaries({
    'effect': effects,
    'principal': principals,
    'action': act_res,
    'resource': act_res,
})

request_strat = st.fixed_dictionaries({
    'subject': st.sampled_from(['alice', 'bob', 'contractor']),
    'roles': roles_strat,
    'action': act_res,
    'resource': act_res,
})


@given(request_strat, st.lists(policy_strat, max_size=5))
@settings(max_examples=300)
def test_hypothesis_fuzz_against_reference(request, policies):
    expected = ref_authorize(request, policies)
    actual = impl.authorize(request, policies)
    assert actual == expected, (request, policies, expected, actual)
